// Package: Microsoft.Azure.Functions.Worker
// Package: Microsoft.Azure.Functions.Worker.Extensions.Http
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Azure.Functions.Worker;

var host = new HostBuilder()
    .ConfigureFunctionsWorkerDefaults(builder =>
    {
        // Apply JSON source-generated serialization (recommended)
        builder.UseMasaAotSerialization();
    })
    .ConfigureServices(services =>
    {
        services.AddSingleton<IWeatherCache, WeatherCache>();
        services.AddHttpClient<IWeatherClient, WeatherClient>(c =>
        {
            c.BaseAddress = new Uri("https://api.weather.example.com");
        });
    })
    .Build();

await host.RunAsync();

// Output: Worker started and listening for function invocations

// Package: Microsoft.Azure.Functions.Worker
// Package: Microsoft.Azure.Functions.Worker.Extensions.Http
using System.Net;
using Microsoft.Azure.Functions.Worker;
using Microsoft.Azure.Functions.Worker.Http;
using Microsoft.Extensions.Logging;

namespace MyFunctionApp;

public class WeatherFunction
{
    private readonly IWeatherCache _cache;
    private readonly ILogger<WeatherFunction> _logger;
    private readonly IWeatherClient _weatherClient;

    public WeatherFunction(
        IWeatherCache cache,
        ILogger<WeatherFunction> logger,
        IWeatherClient weatherClient)
    {
        _cache = cache;
        _logger = logger;
        _weatherClient = weatherClient;
    }

    [Function("get-weather")]
    public async Task<HttpResponseData> GetWeatherAsync(
        [HttpTrigger(AuthorizationLevel.Function, "get", Route = "weather/{city}")]
        HttpRequestData req,
        string city,
        CancellationToken cancellationToken)
    {
        _logger.LogInformation("Fetching weather for {City}", city);

        if (string.IsNullOrWhiteSpace(city))
        {
            var bad = req.CreateResponse(HttpStatusCode.BadRequest);
            await bad.WriteStringAsync("City name is required.", cancellationToken);
            return bad;
        }

        // Try cache first
        if (_cache.TryGet(city, out var cached))
        {
            _logger.LogInformation("Cache hit for {City}", city);
            var cachedResponse = req.CreateResponse(HttpStatusCode.OK);
            await cachedResponse.WriteAsJsonAsync(cached, cancellationToken);
            return cachedResponse;
        }

        try
        {
            var weather = await _weatherClient.GetCurrentAsync(city, cancellationToken);
            _cache.Set(city, weather);

            var response = req.CreateResponse(HttpStatusCode.OK);
            await response.WriteAsJsonAsync(new
            {
                city = weather.City,
                temperatureC = weather.TemperatureC,
                condition = weather.Condition
            }, cancellationToken);
            return response;
        }
        catch (HttpRequestException ex)
        {
            _logger.LogError(ex, "Weather service failed for {City}", city);
            var errorResponse = req.CreateResponse(HttpStatusCode.BadGateway);
            await errorResponse.WriteStringAsync(
                "Weather service temporarily unavailable.", cancellationToken);
            return errorResponse;
        }
    }
}

// --- Supporting interfaces and types ---

public interface IWeatherCache
{
    bool TryGet(string city, out WeatherSummary? summary);
    void Set(string city, WeatherSummary summary);
}

public interface IWeatherClient
{
    Task<WeatherSummary> GetCurrentAsync(string city, CancellationToken ct);
}

public record WeatherSummary(string City, int TemperatureC, string Condition);

public class WeatherCache : IWeatherCache
{
    private readonly Dictionary<string, (WeatherSummary Data, DateTime ExpiresAt)> _store
        = new();

    public bool TryGet(string city, out WeatherSummary? summary)
    {
        lock (_store)
        {
            if (_store.TryGetValue(city, out var entry) && entry.ExpiresAt > DateTime.UtcNow)
            {
                summary = entry.Data;
                return true;
            }
            _store.Remove(city);
        }
        summary = null;
        return false;
    }

    public void Set(string city, WeatherSummary summary)
    {
        lock (_store)
        {
            _store[city] = (summary, DateTime.UtcNow.AddMinutes(10));
        }
    }
}

// Usage (deployed to Azure):
// GET https://<app>.azurewebsites.net/api/weather/london
// Response 200: { "city": "London", "temperatureC": 14, "condition": "Cloudy" }
// Response 400: { message: "City name is required." } if city is blank

// Package: Microsoft.Azure.Functions.Worker
using Microsoft.Azure.Functions.Worker;
using Microsoft.Extensions.Logging;

namespace MyFunctionApp;

public class CleanupFunction
{
    private readonly ILogger<CleanupFunction> _logger;
    private readonly ICleanupService _cleanupService;

    public CleanupFunction(ILogger<CleanupFunction> logger, ICleanupService cleanupService)
    {
        _logger = logger;
        _cleanupService = cleanupService;
    }

    // Runs every day at 02:00 UTC
    // CRON: {second} {minute} {hour} {day} {month} {day-of-week}
    [Function("daily-cleanup")]
    public async Task RunAsync(
        [TimerTrigger("0 0 2 * * *")] TimerInfo timer,
        CancellationToken cancellationToken)
    {
        _logger.LogInformation(
            "Cleanup started at: {Time}. Last run status: {Status}",
            DateTime.UtcNow,
            timer.ScheduleStatus?.LastReason ?? "unknown");

        try
        {
            var removed = await _cleanupService.PurgeExpiredSessionsAsync(cancellationToken);
            _logger.LogInformation("Cleanup complete. Removed {Count} expired sessions.", removed);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Cleanup job failed.");
            throw; // Re-throw to signal failure to the Functions runtime
        }
    }
}

// --- Supporting service ---

public interface ICleanupService
{
    Task<int> PurgeExpiredSessionsAsync(CancellationToken ct);
}

public class CleanupService : ICleanupService
{
    public async Task<int> PurgeExpiredSessionsAsync(CancellationToken ct)
    {
        // Implementation: query expired sessions, delete them, return count
        await Task.CompletedTask;
        return 0;
    }
}

